'use strict';
const M=window.EssenceDemo,canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);
let state=M.create(),images={},ready=false,paused=false,previous=0,width=0,height=0,scale=1,ox=0,oy=0,dpr=1,noticeId=0,messageUntil=0,castHeld=false,raf=0;
const keys=new Set(),touches=new Map(),reduced=matchMedia('(prefers-reduced-motion: reduce)');
const camera={x:510,y:490};
const assets={hero:'hero.png',rogue:'rogue.png',mage:'mage.png',grass:'grass.png',path:'path.png',stone:'stone.png',tree:'tree.png',tree2:'tree2.png',pine:'pine.png',portal:'portal.png',spell:'apocalipsis_60.png'};
const floor=document.createElement('canvas');floor.width=M.WIDTH;floor.height=M.HEIGHT;
function loadImage(name,file){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[name]=im;resolve();};im.onerror=()=>reject(Error(file));im.src='../assets/'+file;});}
async function load(){ready=false;$('#retry').hidden=true;$('#curtain').hidden=false;$('#curtain-title').textContent='Opening the portal…';try{await Promise.all(Object.entries(assets).map(([n,f])=>loadImage(n,f)));buildFloor();ready=true;$('#curtain').hidden=true;canvas.focus({preventScroll:true});resize();schedule();}catch(e){$('#curtain-title').textContent='The portal could not open';$('#curtain-text').textContent='An artwork file did not load. Please try again.';$('#retry').hidden=false;}}
function buildFloor(){const c=floor.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle=c.createPattern(images.grass,'repeat');c.fillRect(0,0,M.WIDTH,M.HEIGHT);c.save();c.beginPath();c.rect(130,400,860,100);c.rect(570,320,90,480);c.rect(150,470,95,220);c.clip();for(let y=0;y<M.HEIGHT;y+=40)for(let x=0;x<M.WIDTH;x+=40)c.drawImage(images.path,x,y,40,40);c.restore();for(let y=330;y<520;y+=40)for(let x=50;x<270;x+=40)c.drawImage(images.stone,x,y,40,40);const shade=c.createRadialGradient(580,450,100,580,450,780);shade.addColorStop(0,'#203a2610');shade.addColorStop(1,'#03120ed9');c.fillStyle=shade;c.fillRect(0,0,M.WIDTH,M.HEIGHT);}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;scale=width<760?Math.max(.72,Math.min(width/560,height/760)):Math.min(width/1100,height/790);schedule();}
function ellipse(x,y,rx,ry,color,line=false){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);if(line){ctx.strokeStyle=color;ctx.lineWidth=2;ctx.stroke();}else{ctx.fillStyle=color;ctx.fill();}}
function text(s,x,y,color='#e6e4cc',size=13){ctx.font=`${size}px Inter, sans-serif`;ctx.textAlign='center';ctx.fillStyle='#07120f';ctx.fillText(s,x+1,y+2);ctx.fillStyle=color;ctx.fillText(s,x,y);}
function actor(a,body,player=false){const im=images[body];const f=a.moving?1+Math.floor(a.gait/64*7)%7:0;ellipse(a.x,a.y+1,16,5,'#00110cc0');if(player)ellipse(a.x,a.y+2,20,8,'#e8d491',true);ctx.drawImage(im,f*96,a.dir*160,96,160,Math.round(a.x-30),Math.round(a.y-91),60,100);}
function portal(){const frame=reduced.matches?0:Math.floor(state.time*10)%8;const p=M.gateway;ctx.save();ctx.shadowColor='#bddd66';ctx.shadowBlur=reduced.matches?0:22;ctx.drawImage(images.portal,(frame%4)*240,Math.floor(frame/4)*320,240,320,p.x-96,p.y-248,192,256);ctx.restore();text(state.phase==='threshold'?'THE CROSSING':'RETURN & SECURE',p.x,p.y+32,'#d8e9b1',13);}
function draw(){if(!ready)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#091911';ctx.fillRect(0,0,width,height);const p=state.player;
 const targetX=width<760?p.x:state.phase==='threshold'?490:600;const targetY=width<760?p.y-50:500;camera.x=targetX;camera.y=targetY;ox=width/2-camera.x*scale;oy=height*.53-camera.y*scale;
 ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.imageSmoothingEnabled=false;ctx.drawImage(floor,0,0);
 if(state.phase==='arena'){ctx.fillStyle='#83d7b41a';ctx.fillRect(38,300,232,330);ctx.setLineDash([5,8]);ctx.strokeStyle='#b7d99588';ctx.beginPath();ctx.moveTo(270,310);ctx.lineTo(270,650);ctx.stroke();ctx.setLineDash([]);text('SANCTUARY',164,600,'#a8d8b5',12);}
 for(const e of state.enemies){if(state.phase!=='arena'||e.hp<=0)continue;if(e.wind>0){ellipse(e.x,e.y,70*(1-e.wind/.85),27*(1-e.wind/.85),'#e7966955');ellipse(e.x,e.y,70,27,'#f0a16a',true);}else ellipse(e.x,e.y+2,25,10,'#db9b6655',true);}
 const layers=[...M.scenery.map(s=>({...s,type:'scenery'})),{type:'portal',y:M.gateway.y},...(state.phase==='arena'?state.enemies.filter(e=>e.hp>0):[]),{...p,body:'hero',player:true}].sort((a,b)=>a.y-b.y);
 for(const a of layers){if(a.type==='scenery')ctx.drawImage(images[a.id],a.x-a.w/2,a.y-a.h,a.w,a.h);else if(a.type==='portal')portal();else actor(a,a.body,a.player);}
 if(state.phase==='arena')for(const e of state.enemies){if(e.hp<=0)continue;text(e.name,e.x,e.y-98,'#d9c79c',12);const max=e.reward===15?2:3;ctx.fillStyle='#16251b';ctx.fillRect(e.x-21,e.y-91,42,4);ctx.fillStyle=e.wind?'#f2a16c':'#cbad70';ctx.fillRect(e.x-21,e.y-91,42*e.hp/max,4);}
 for(const f of state.fx){const frame=Math.min(31,Math.floor(f.age*16));if(reduced.matches){ellipse(f.x,f.y,35,20,'#e8d5a7',true);}else ctx.drawImage(images.spell,(frame%4)*273,Math.floor(frame/4)*243,273,243,f.x-73,f.y-65,146,130);}
 if(state.carried){text(`✦ ${state.carried}`,p.x,p.y-112,'#f3d586',15);}
 ctx.setTransform(dpr,0,0,dpr,0,0);if(state.flash&&!reduced.matches){ctx.fillStyle=`rgba(200,230,158,${state.flash*.35})`;ctx.fillRect(0,0,width,height);}
}
function ui(){const p=state.player;$('#health-fill').style.width=p.hp+'%';$('#health').textContent=Math.ceil(p.hp)+' / 100';$('#carried').textContent=state.carried;$('#secured').textContent=state.secured;$('#chapter').textContent=state.phase==='threshold'?'NIX / THE THRESHOLD':'THE VEIL / TRAINING GROUNDS';$('#objective-label').textContent=state.phase==='threshold'?'YOUR FIRST CROSSING':state.won?'THE LOOP IS YOURS':'SECURE 60 ESSENCE';$('#objective').textContent=state.phase==='threshold'?'Step into the unknown':state.won?'Risk. Return. Grow.':state.carried?'Carry it home. Or stay.':'Something worth fighting for';$('#hint').textContent=state.phase==='threshold'?'Walk up to the portal. Press E to enter.':state.carried?'Your carried essence is lost if you fall. Secured essence stays.':`Defeat training rivals. ${state.secured} / 60 essence secured.`;const near=M.nearGate(state);$('#interact').disabled=!near||state.bank>0||paused;$('#interact').innerHTML=state.phase==='threshold'?(near?'Enter the portal <kbd>E</kbd>':'Approach the portal <kbd>E</kbd>'):state.bank?'Securing essence…':near&&state.carried?'Secure '+state.carried+' essence <kbd>E</kbd>':near?'Sanctuary · essence stays safe':'Return to the portal to secure';$('#bank-progress').hidden=!state.bank;$('#bank-progress span').style.width=Math.min(100,state.bank/1.5*100)+'%';$('#cast').disabled=state.phase!=='arena'||paused;$('#cast').style.opacity=state.cooldown>0?'.55':'1';if(state.noticeId!==noticeId){noticeId=state.noticeId;$('#message').textContent=state.notice;messageUntil=performance.now()+4500;}$('#message').classList.toggle('visible',performance.now()<messageUntil);}
function input(){const x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);return {x,y};}
function tick(now){raf=0;const dt=Math.min((now-previous)/1000||0,.04);previous=now;if(ready&&!paused&&!document.hidden){M.update(state,dt,input());if(castHeld||keys.has(' '))M.cast(state);}draw();ui();if(ready&&!document.hidden)schedule();}
function schedule(){if(!raf&&!document.hidden)raf=requestAnimationFrame(tick);}
function clear(){keys.clear();touches.clear();castHeld=false;}
function togglePause(value=!paused){if(!ready)return;paused=value;clear();$('#curtain').hidden=!paused;$('#curtain-title').textContent='A moment of stillness';$('#curtain-text').textContent='Your rivals and essence will wait.';$('#resume').hidden=!paused;$('#pause').textContent=paused?'Resume':'Pause P';$('#pause').setAttribute('aria-pressed',String(paused));if(!paused)canvas.focus({preventScroll:true});schedule();}
const accepted=['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright',' '];document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='p'||key==='escape'){if(!e.repeat)togglePause();return;}if(e.target.closest('button,a'))return;if(accepted.includes(key)){e.preventDefault();if(ready&&!paused)keys.add(key);}if(key==='e'&&!e.repeat&&ready&&!paused)M.interact(state);});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
const mapping={up:'w',left:'a',down:'s',right:'d'};for(const button of document.querySelectorAll('[data-dir]')){button.addEventListener('pointerdown',e=>{e.preventDefault();if(paused||!ready)return;button.setPointerCapture(e.pointerId);touches.set(e.pointerId,mapping[button.dataset.dir]);keys.add(mapping[button.dataset.dir]);});const release=e=>{const key=touches.get(e.pointerId);touches.delete(e.pointerId);if(![...touches.values()].includes(key))keys.delete(key);};button.addEventListener('pointerup',release);button.addEventListener('pointercancel',release);button.addEventListener('lostpointercapture',release);}
$('#cast').addEventListener('pointerdown',e=>{e.preventDefault();if(paused||!ready)return;$('#cast').setPointerCapture(e.pointerId);castHeld=true;M.cast(state);});for(const type of ['pointerup','pointercancel','lostpointercapture'])$('#cast').addEventListener(type,()=>castHeld=false);$('#cast').addEventListener('click',e=>{if(e.detail===0&&!paused)M.cast(state);});
$('#interact').onclick=()=>{if(ready&&!paused)M.interact(state);canvas.focus({preventScroll:true});};$('#pause').onclick=()=>togglePause();$('#resume').onclick=()=>togglePause(false);$('#restart').onclick=()=>{if(!ready)return;state=M.create();noticeId=0;messageUntil=0;togglePause(false);};$('#retry').onclick=load;
canvas.addEventListener('pointerdown',()=>canvas.focus({preventScroll:true}));window.addEventListener('blur',()=>{clear();if(ready&&!paused)togglePause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden){clear();if(ready&&!paused)togglePause(true);if(raf)cancelAnimationFrame(raf);raf=0;}else{previous=performance.now();schedule();}});window.addEventListener('resize',resize);resize();load();
